.ds-shell-pill {
  --fi-shell-pill-h: 44px;
  --fi-shell-pill-pad-y: 6px;
  display: inline-flex;
  min-height: var(--fi-shell-pill-h);
  box-sizing: border-box;
  align-items: center;
  gap: 8px;
  padding: var(--fi-shell-pill-pad-y) 14px;
  border: var(--fi-stroke-main) solid var(--fi-border-primary);
  border-radius: var(--fi-radius-pill);
  background: var(--fi-surface-raised);
  color: var(--fi-text-primary);
  box-shadow: 2px 2px 0 var(--fi-shadow-subtle);
  font-family: var(--fi-font-body);
  font-size: var(--fi-type-ui);
  transition: background var(--fi-motion-day-night-flip) ease, color var(--fi-motion-day-night-flip) ease, border-color var(--fi-motion-day-night-flip) ease;
} .ds-lang-active { color: var(--fi-accent-emphasis); font-weight: 700; } .ds-shell-pill { cursor: pointer; } .ds-shell-pill:focus-visible { outline: 3px solid color-mix(in srgb, var(--fi-gamboge) 78%, transparent); outline-offset: 3px; } .ds-shell-pill:hover { background: var(--fi-surface-raised); }
